import type { Genre } from '@/shared/types/chart';
import type { TrackPalette } from '@/shared/lib/render/themes';

/** Catalog entry — generated by `scripts/generate-charts.ts` into `catalog.json`, sorted by stars. */
export interface TrackMeta {
  id: string;
  title: string;
  artist: string;
  license: string;
  sourceUrl: string;
  genre: Genre;
  /** Premium track — sold in the shop for crystals; absent for the free catalog. */
  premium?: boolean;
  /** Named pack (`rock`) — a chapter of its own after the numbered ones; absent for the main catalog. */
  pack?: string;
  /** Picture cover, a path under `public/` (`covers/<id>.webp`); absent → procedural art. */
  cover?: string;
  /** The picture's accent colour (`#rrggbb`) for the play button; absent → the procedural palette's accent. */
  tint?: string;
  /** The level's colours from the picture (lanes, background, glow); absent → the genre theme. */
  palette?: TrackPalette;
  bpm: number;
  duration: number;
  /** Difficulty of the song's chart, 1–10. */
  stars: number;
  notes: number;
  /** Quick mechanic summary shown on the card. */
  features: { circles: number; rolls: number; slides: number; holds: number; laneChanges: number };
}
